              <span className="material-icons">contact_phone</span>
              <span className="contact-text">Contact owner for details</span>
            </div>
          )}
        </div>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-blue-50">
      <header className="sticky top-0 z-50 backdrop-blur-md bg-gradient-to-r from-slate-50/95 to-blue-50/95 shadow-lg border-b border-blue-200">
        <div className="max-w-full mx-auto px-6 py-4">
          <div className="flex items-center justify-between gap-4">
            <div className="flex items-center gap-3">
              <div className="text-2xl font-bold bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                PET_RESCUE_APP
              </div>
            </div>
            <div className="flex-1 text-center">
              <span className="text-lg font-semibold text-primary-blue">
                WELCOME: {user?.username?.toUpperCase() || "USER_NAME"}
              </span>
            </div>
            <div className="flex items-center gap-4">
              <button
                className="p-2 rounded-full hover:bg-blue-100 transition-all duration-300 disabled:opacity-50"
                onClick={loadData}
                disabled={loading}
                title="Refresh Data"
              >
                <span className="material-icons text-primary-blue">
                  refresh
                </span>
              </button>
              <div className="relative">
                <button
                  className="p-2 rounded-full hover:bg-blue-100 transition-all duration-300 relative"
                  onClick={handleNotificationDropdownToggle}
                >
                  <span className="material-icons text-primary-blue">
                    notifications
                  </span>
                  {unreadCount > 0 && !showNotifications && (
                    <span className="absolute -top-1 -right-1 bg-red-500 text-white text-xs font-bold rounded-full w-5 h-5 flex items-center justify-center">
                      {unreadCount}
                    </span>
                  )}
                </button>
                {showNotifications && (
                  <div className="absolute right-0 mt-2 w-96 bg-gradient-to-br from-slate-50 to-blue-50 rounded-2xl shadow-2xl border border-blue-200 overflow-hidden z-50 max-h-[500px] flex flex-col">
                    <div className="flex items-center justify-between p-4 bg-gradient-to-r from-primary-blue to-primary-teal border-b border-blue-200">
                      <h3 className="text-white font-semibold text-lg">
                        Notifications
                      </h3>
                      <button
                        className="text-white hover:bg-white/20 rounded-full p-1 transition-colors"
                        onClick={(e) => {
                          e.stopPropagation();
                          setShowNotifications(false);
                        }}
                      >
                        <span className="text-2xl leading-none">×</span>
                      </button>
                    </div>
                    <div className="overflow-y-auto flex-1">
                      {notifications.length === 0 ? (
                        <div className="flex flex-col items-center justify-center py-12 text-gray-400">
                          <span className="material-icons text-6xl mb-2">
                            notifications_none
                          </span>
                          <p className="text-sm">No notifications yet</p>
                        </div>
                      ) : (
                        notifications.map((notification) => (
                          <div
                            key={notification.id}
                            className={`p-4 border-b border-blue-100 hover:bg-blue-100 transition-colors cursor-pointer ${
                              notification.is_read
                                ? "bg-slate-50"
                                : "bg-blue-50/50"
                            }`}
                            onClick={() =>
                              handleNotificationClick(notification.id)
                            }
                          >
                            <div className="flex items-start justify-between gap-3">
                              <div className="flex-1">
                                <h4
                                  className={`text-sm ${
                                    notification.is_read
                                      ? "text-gray-600"
                                      : "text-primary-blue font-bold"
                                  }`}
                                >
                                  {notification.title}
                                </h4>
                                <p className={`text-sm mt-1 ${
                                  notification.is_read
                                    ? "text-gray-500"
                                    : "text-gray-700 font-semibold"
                                }`}>
                                  {notification.message}
                                </p>
                                <span className="text-xs text-gray-400 mt-2 block">
                                  {new Date(
                                    notification.created_at
                                  ).toLocaleDateString()}
                                </span>
                              </div>
                              <button
                                className="p-1 hover:bg-red-100 rounded-full transition-colors"
                                onClick={(e) => {
                                  e.stopPropagation();
                                  handleDeleteNotification(notification.id);
                                }}
                              >
                                <span className="material-icons text-red-500 text-lg">
                                  delete
                                </span>
                              </button>
                            </div>
                          </div>
                        ))
                      )}
                    </div>
                  </div>
                )}
              </div>
              <div className="relative">
                <button
                  className="w-10 h-10 rounded-full bg-gradient-to-br from-primary-blue to-primary-teal text-white font-bold text-lg flex items-center justify-center hover:shadow-lg transition-all duration-300 hover:scale-110"
                  onClick={() => setShowProfileDropdown((prev) => !prev)}
                >
                  {user?.username?.charAt(0).toUpperCase() || "U"}
                </button>
                {showProfileDropdown && (
                  <div className="absolute right-0 mt-2 w-48 bg-gradient-to-br from-slate-50 to-blue-50 rounded-xl shadow-xl border border-blue-200 overflow-hidden z-50">
                    <button
                      className="w-full px-4 py-3 text-left hover:bg-blue-100 transition-colors text-gray-700 hover:text-primary-blue font-medium"
                      onClick={() => {
                        setActiveTab("profile");
                        setShowProfileDropdown(false);
                      }}
                    >
                      Edit Profile
                    </button>
                    <button
                      className="w-full px-4 py-3 text-left hover:bg-red-50 transition-colors text-red-600 hover:text-red-700 font-medium border-t border-gray-100"
                      onClick={() => {
                        // Clear token from localStorage
                        localStorage.removeItem("token");

                        // Optionally clear other user-related data
                        // localStorage.removeItem('user');

                        // Redirect to login page
                        window.location.href = "/login";
                      }}
                    >
                      Logout
                    </button>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
        {/* Horizontal Navigation Bar */}
        <nav className="bg-gradient-to-r from-primary-blue via-primary-teal to-primary-teal border-t border-blue-200">
          <ul className="flex items-center justify-center gap-1 px-4 max-w-7xl mx-auto overflow-x-auto">
            <li
              className={`flex items-center gap-2 px-4 py-4 cursor-pointer transition-all duration-300 whitespace-nowrap ${
                activeTab === "dashboard"
                  ? "bg-white/20 border-b-4 border-accent-yellow text-white"
                  : "text-white/80 hover:bg-white/10 hover:text-white"
              }`}
              onClick={() => setActiveTab("dashboard")}
            >
              <span className="material-icons text-lg">dashboard</span>
              <span className="font-semibold text-xs">DASHBOARD</span>
            </li>
            <li
              className={`flex items-center gap-2 px-4 py-4 cursor-pointer transition-all duration-300 whitespace-nowrap ${
                activeTab === "report-lost"
                  ? "bg-white/20 border-b-4 border-accent-yellow text-white"
                  : "text-white/80 hover:bg-white/10 hover:text-white"
              }`}
              onClick={() => setActiveTab("report-lost")}
            >
              <span className="material-icons text-lg">report</span>
              <span className="font-semibold text-xs">REPORT LOST</span>
            </li>
            <li
              className={`flex items-center gap-2 px-4 py-4 cursor-pointer transition-all duration-300 whitespace-nowrap ${
                activeTab === "report-found"
                  ? "bg-white/20 border-b-4 border-accent-yellow text-white"
                  : "text-white/80 hover:bg-white/10 hover:text-white"
              }`}
              onClick={() => setActiveTab("report-found")}
            >
              <span className="material-icons text-lg">visibility</span>
              <span className="font-semibold text-xs">REPORT FOUND</span>
            </li>
            <li
              className={`flex items-center gap-2 px-4 py-4 cursor-pointer transition-all duration-300 whitespace-nowrap ${
                activeTab === "all-lost"
                  ? "bg-white/20 border-b-4 border-accent-yellow text-white"
                  : "text-white/80 hover:bg-white/10 hover:text-white"
              }`}
              onClick={() => setActiveTab("all-lost")}
            >
              <span className="material-icons text-lg">pets</span>
              <span className="font-semibold text-xs">ALL LOST</span>
            </li>
            <li
              className={`flex items-center gap-2 px-4 py-4 cursor-pointer transition-all duration-300 whitespace-nowrap ${
                activeTab === "explore-adoption"
                  ? "bg-white/20 border-b-4 border-accent-yellow text-white"
                  : "text-white/80 hover:bg-white/10 hover:text-white"
              }`}
              onClick={() => setActiveTab("explore-adoption")}
            >
              <span className="material-icons text-lg">favorite</span>
              <span className="font-semibold text-xs">EXPLORE</span>
            </li>
            <li
              className={`flex items-center gap-2 px-4 py-4 cursor-pointer transition-all duration-300 whitespace-nowrap ${
                activeTab === "post-pet-adoption"
                  ? "bg-white/20 border-b-4 border-accent-yellow text-white"
                  : "text-white/80 hover:bg-white/10 hover:text-white"
              }`}
              onClick={() => setActiveTab("post-pet-adoption")}
            >
              <span className="material-icons text-lg">add_circle</span>
              <span className="font-semibold text-xs">POST PET</span>
            </li>
            <li
              className={`flex items-center gap-2 px-4 py-4 cursor-pointer transition-all duration-300 whitespace-nowrap ${
                activeTab === "notifications"
                  ? "bg-white/20 border-b-4 border-accent-yellow text-white"
                  : "text-white/80 hover:bg-white/10 hover:text-white"
              }`}
              onClick={() => setActiveTab("notifications")}
            >
              <span className="material-icons text-lg">notifications</span>
              <span className="font-semibold text-xs">NOTIFICATIONS</span>
            </li>
          </ul>
        </nav>
      </header>

      <div
        className="overflow-y-auto"
        style={{ height: "calc(100vh - 180px)" }}
      >
        <div className="max-w-7xl mx-auto px-6 py-8">
          <main>
            {error && (
              <div className="bg-red-50 border-l-4 border-red-500 p-4 mb-6 rounded-r-lg">
                <p className="text-red-700 font-medium">{error}</p>
              </div>
            )}
            {successMessage && (
              <div className="bg-green-50 border-l-4 border-green-500 p-4 mb-6 rounded-r-lg">
                <p className="text-green-700 font-medium">{successMessage}</p>
              </div>
            )}

            {activeTab === "dashboard" &&
              (loading ? (
                <div className="flex items-center justify-center py-20">
                  <div className="text-center">
                    <div className="animate-spin rounded-full h-16 w-16 border-b-4 border-primary-blue mx-auto"></div>
                    <p className="mt-4 text-gray-600 font-medium">Loading...</p>
                  </div>
                </div>
              ) : (
                <div className="space-y-4">
                  {/* Section 1: YOUR LOST REPORTS */}
                  <div className="bg-gradient-to-br from-slate-50 to-blue-50 rounded-2xl shadow-lg border border-blue-100 overflow-hidden">
                    <button
                      onClick={() =>
                        setExpandedSection(
                          expandedSection === "lostReports"
                            ? null
                            : "lostReports"
                        )
                      }
                      className="w-full flex items-center justify-between p-6 hover:bg-blue-50 transition-colors"
                    >
                      <div className="flex items-center gap-3">
                        <span className="material-icons text-primary-blue text-3xl">
                          list
                        </span>
                        <h2 className="text-2xl font-bold text-gray-800">
                          YOUR LOST REPORTS ({lostReports.length})
                        </h2>
                      </div>
                      <span
                        className={`material-icons text-3xl text-primary-blue transition-transform ${
                          expandedSection === "lostReports" ? "rotate-180" : ""
                        }`}
                      >
                        expand_more
                      </span>
                    </button>

                    {expandedSection === "lostReports" && (
                      <div className="p-6 pt-0">
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                          {lostReports.length > 0 ? (
                            lostReports.map((report) => (
                              <div
                                key={report.id}
                                className="bg-white rounded-2xl shadow-lg overflow-hidden hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-2 border border-blue-100"
                              >
                                <div className="relative h-56 overflow-hidden">
                                  <img
                                    src={getImageUrl(report.photo)}
                                    alt={report.pet_name}
                                    className="w-full h-full object-cover"
                                    onError={(e) => {
                                      e.target.src = getDefaultImage(
                                        report.animal_type
                                      );
                                    }}
                                  />
                                  <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/70 to-transparent p-4">
                                    <h3 className="text-white font-bold text-lg">
                                      {report.pet_name}
                                    </h3>
                                  </div>
                                </div>
                                <div className="p-5 space-y-3">
                                  <div className="inline-block px-3 py-1 bg-blue-100 text-primary-blue rounded-full text-sm font-semibold">
                                    {report.animal_type}
                                  </div>
                                  <div className="space-y-2">
                                    {report.pet_breed && (
                                      <span className="block text-gray-700 text-sm">
                                        <span className="font-semibold">
                                          Breed:
                                        </span>{" "}
                                        {report.pet_breed}
                                      </span>
                                    )}
                                    {report.pet_location && (
                                      <span className="flex items-center gap-1 text-gray-700 text-sm">
                                        <span className="material-icons text-xs">
                                          location_on
                                        </span>
                                        {report.pet_location}
                                      </span>
                                    )}
                                  </div>
                                  <p className="text-gray-600 text-sm leading-relaxed">
                                    {report.description
                                      ? report.description.length > 50
                                        ? `${report.description.substring(
                                            0,
                                            50
                                          )}...`
                                        : report.description
                                      : "No description available"}
                                  </p>
                                  <div className="flex items-center justify-between pt-2 border-t border-gray-100">
                                    <span className="text-xs text-gray-500">
                                      {new Date(
                                        report.created_at
                                      ).toLocaleDateString()}
                                    </span>
                                  </div>
                                  <div
                                    className={`px-3 py-2 rounded-lg text-center font-semibold text-sm ${
                                      report.status.toLowerCase() ===
                                        "approved" ||
                                      report.status.toLowerCase() === "accepted"
                                        ? "bg-green-100 text-green-700"
                                        : report.status.toLowerCase() ===
                                          "pending"
                                        ? "bg-yellow-100 text-yellow-700"
                                        : report.status.toLowerCase() ===
                                          "reunited"
                                        ? "bg-blue-100 text-blue-700"
                                        : "bg-red-100 text-red-700"
                                    }`}
                                  >
                                    Status:{" "}
                                    <strong>
                                      {report.status.toUpperCase()}
                                    </strong>
                                  </div>

                                  {/* View Details Button */}
                                  <button
                                    className="w-full px-4 py-2 bg-gradient-to-r from-blue-500 to-cyan-500 text-white font-semibold rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-300 flex items-center justify-center gap-2 mt-2"
                                    onClick={() => {
                                      if (report.pet_id) {
                                        fetchPetDetails(report.pet_id);
                                      } else {
                                        setError(
                                          "Pet ID not available for this report"
                                        );
                                        setTimeout(() => setError(""), 3000);
                                      }
                                    }}
                                  >
                                    <span className="material-icons text-sm">
                                      visibility
                                    </span>
                                    View Details
                                  </button>

                                  {/* Action Buttons */}
                                  <div className="flex gap-2 mt-3">
                                    {/* Reunite button - only for ACCEPTED/APPROVED reports */}
                                    {(report.status.toLowerCase() ===
                                      "accepted" ||
                                      report.status.toLowerCase() ===
                                        "approved") &&
                                      report.status.toLowerCase() !==
                                        "reunited" && (
                                        <button
                                          className="flex-1 px-4 py-2 bg-gradient-to-r from-green-500 to-teal-500 text-white font-semibold rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-300 flex items-center justify-center gap-2"
                                          onClick={() =>
                                            handleReuniteReport(report.id)
                                          }
                                        >
                                          <span className="material-icons text-sm">
                                            celebration
                                          </span>
                                          Reunite
                                        </button>
                                      )}
                                    {/* Delete button - always available */}
                                    <button
                                      className="flex-1 px-4 py-2 bg-gradient-to-r from-red-500 to-pink-500 text-white font-semibold rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-300 flex items-center justify-center gap-2"
                                      onClick={() =>
                                        handleDeleteReport(report.id)
                                      }
                                    >
                                      <span className="material-icons text-sm">
                                        delete
                                      </span>
                                      Delete
                                    </button>
                                  </div>
                                </div>
                              </div>
                            ))
                          ) : (
                            <div className="col-span-full text-center py-12">
                              <span className="material-icons text-6xl text-gray-300 mb-4">
                                pets
                              </span>
                              <p className="text-gray-500 text-lg">
                                No lost pet reports yet
                              </p>
                            </div>
                          )}
                        </div>
                      </div>
                    )}
                  </div>

                  {/* Section 2: YOUR RESCUE PET REPORTS */}
                  <div className="bg-gradient-to-br from-slate-50 to-blue-50 rounded-2xl shadow-lg border border-blue-100 overflow-hidden">
                    <button
                      onClick={() =>
                        setExpandedSection(
                          expandedSection === "rescueReports"
                            ? null
                            : "rescueReports"
                        )
                      }
                      className="w-full flex items-center justify-between p-6 hover:bg-blue-50 transition-colors"
                    >
                      <div className="flex items-center gap-3">
                        <span className="material-icons text-primary-teal text-3xl">
                          search
                        </span>
                        <h2 className="text-2xl font-bold text-gray-800">
                          YOUR RESCUE PET REPORTS ({rescueReports.length})
                        </h2>
                      </div>
                      <span
                        className={`material-icons text-3xl text-primary-teal transition-transform ${
                          expandedSection === "rescueReports"
                            ? "rotate-180"
                            : ""
                        }`}
                      >
                        expand_more
                      </span>
                    </button>

                    {expandedSection === "rescueReports" && (
                      <div className="p-6 pt-0">
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                          {rescueReports.length > 0 ? (
                            rescueReports.map((report) => (
                              <div
                                key={report.id}
                                className="bg-white rounded-2xl shadow-lg overflow-hidden hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-2 border border-blue-100"
                              >
                                <div className="relative h-56 overflow-hidden">
                                  <img
                                    src={getImageUrl(report.photo)}
                                    alt={report.pet_name}
                                    className="w-full h-full object-cover"
                                    onError={(e) => {
                                      e.target.src = getDefaultImage(
                                        report.animal_type
                                      );
                                    }}
                                  />
                                  <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/70 to-transparent p-4">
                                    <h3 className="text-white font-bold text-lg">
                                      {report.pet_name}
                                    </h3>
                                  </div>
                                </div>
                                <div className="p-5 space-y-3">
                                  <div className="inline-block px-3 py-1 bg-teal-100 text-primary-teal rounded-full text-sm font-semibold">
                                    {report.animal_type}
                                  </div>
                                  <div className="space-y-2">
                                    {report.pet_breed && (
                                      <span className="block text-gray-700 text-sm">
                                        <span className="font-semibold">
                                          Breed:
                                        </span>{" "}
                                        {report.pet_breed}
                                      </span>
                                    )}
                                    {report.pet_location && (
                                      <span className="flex items-center gap-1 text-gray-700 text-sm">
                                        <span className="material-icons text-xs">
                                          location_on
                                        </span>
                                        {report.pet_location}
                                      </span>
                                    )}
                                  </div>
                                  <p className="text-gray-600 text-sm leading-relaxed">
                                    {report.description
                                      ? report.description.length > 50
                                        ? `${report.description.substring(
                                            0,
                                            50
                                          )}...`
                                        : report.description
                                      : "No description available"}
                                  </p>
                                  <div className="flex items-center justify-between pt-2 border-t border-gray-100">
                                    <span className="text-xs text-gray-500">
                                      {new Date(
                                        report.created_at
                                      ).toLocaleDateString()}
                                    </span>
                                  </div>
                                  <div
                                    className={`px-3 py-2 rounded-lg text-center font-semibold text-sm ${
                                      report.status.toLowerCase() ===
                                        "approved" ||
                                      report.status.toLowerCase() === "accepted"
                                        ? "bg-green-100 text-green-700"
                                        : report.status.toLowerCase() ===
                                          "pending"
                                        ? "bg-yellow-100 text-yellow-700"
                                        : report.status.toLowerCase() ===
                                          "reunited"
                                        ? "bg-blue-100 text-blue-700"
                                        : "bg-red-100 text-red-700"
                                    }`}
                                  >
                                    Status:{" "}
                                    <strong>
                                      {report.status.toUpperCase()}
                                    </strong>
                                  </div>

                                  {/* View Details Button */}
                                  <button
                                    className="w-full px-4 py-2 bg-gradient-to-r from-teal-500 to-cyan-500 text-white font-semibold rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-300 flex items-center justify-center gap-2 mt-2"
                                    onClick={() => {
                                      if (report.pet_id) {
                                        fetchPetDetails(report.pet_id);
                                      } else {
                                        setError(
                                          "Pet ID not available for this report"
                                        );
                                        setTimeout(() => setError(""), 3000);
                                      }
                                    }}
                                  >
                                    <span className="material-icons text-sm">
                                      visibility
                                    </span>
                                    View Details
                                  </button>

                                  {/* Action Buttons */}
                                  <div className="flex gap-2 mt-3">
                                    {/* Reunite button - only for ACCEPTED/APPROVED reports */}
                                    {(report.status.toLowerCase() ===
                                      "accepted" ||
                                      report.status.toLowerCase() ===
                                        "approved") &&
                                      report.status.toLowerCase() !==
                                        "reunited" && (
                                        <button
                                          className="flex-1 px-4 py-2 bg-gradient-to-r from-green-500 to-teal-500 text-white font-semibold rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-300 flex items-center justify-center gap-2"
                                          onClick={() =>
                                            handleReuniteReport(report.id)
                                          }
                                        >
                                          <span className="material-icons text-sm">
                                            celebration
                                          </span>
                                          Reunite
                                        </button>
                                      )}
                                    {/* Delete button - always available */}
                                    <button
                                      className="flex-1 px-4 py-2 bg-gradient-to-r from-red-500 to-pink-500 text-white font-semibold rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-300 flex items-center justify-center gap-2"
                                      onClick={() =>
                                        handleDeleteReport(report.id)
                                      }
                                    >
                                      <span className="material-icons text-sm">
                                        delete
                                      </span>
                                      Delete
                                    </button>
                                  </div>
                                </div>
                              </div>
                            ))
                          ) : (
                            <div className="col-span-full text-center py-12">
                              <span className="material-icons text-6xl text-gray-300 mb-4">
                                search
                              </span>
                              <p className="text-gray-500 text-lg">
                                No rescue pet reports yet
                              </p>
                            </div>
                          )}
                        </div>
                      </div>
                    )}
                  </div>

                  {user?.role === "admin" && adminMetrics && (
                    <div className="admin-metrics">
                      <h3>Admin Dashboard Metrics</h3>
                      <ul>
                        <li>
                          Total Pets Reported:{" "}
                          {adminMetrics.total_pets_reported}
                        </li>
                        <li>
                          Total Adoptions Approved:{" "}
                          {adminMetrics.total_adoptions_approved}
                        </li>
                        <li>Total Lost: {adminMetrics.total_lost}</li>
                        <li>Total Found: {adminMetrics.total_found}</li>
                        <li>
                          Total Registered Users:{" "}
                          {adminMetrics.total_registered_users}
                        </li>
                        <li>
                          Total Cases Resolved:{" "}
                          {adminMetrics.total_cases_resolved}
                        </li>
                      </ul>
                      {metricsMsg && <div>{metricsMsg}</div>}
                    </div>
                  )}

