                                    <span className="material-icons text-sm">
                                      visibility
                                    </span>
                                    View Details
                                  </button>

                                  {/* Delete Button for Adoption Posts */}
                                  <button
                                    className="w-full px-4 py-2 bg-gradient-to-r from-red-500 to-pink-500 text-white font-semibold rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-300 flex items-center justify-center gap-2 mt-2"
                                    onClick={() => handleDeleteReport(post.id)}
                                  >
                                    <span className="material-icons text-sm">
                                      delete
                                    </span>
                                    Delete Post
                                  </button>
                                </div>
                              </div>
                            ))
