                              <span className="px-2 py-1 bg-green-100 text-green-700 text-xs font-semibold rounded-lg flex items-center gap-1">
                                ✓ Vaccinated
                              </span>
                            )}
                            {pet.is_diseased && (
                              <span className="px-2 py-1 bg-yellow-100 text-yellow-700 text-xs font-semibold rounded-lg flex items-center gap-1">
                                ⚠ Health Condition
                              </span>
                            )}
