                              }
                              className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors"
                              placeholder="e.g., Rabies, DHPP"
                            />
                          </div>
                        </div>
                        <div className="flex flex-col">
                          <label className="text-sm font-semibold text-gray-700 mb-2">
                            Vaccination Certificate
                          </label>
                          <input
                            type="file"
                            accept=".pdf,.jpg,.jpeg,.png"
                            onChange={(e) =>
                              setPostAdoptionForm({
                                ...postAdoptionForm,
                                vaccination_certificate: e.target.files[0],
                              })
                            }
                            className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-primary-blue file:text-white hover:file:bg-primary-teal file:cursor-pointer"
                          />
                          <p className="text-xs text-gray-500 mt-2">
                            Upload PDF or image file
                          </p>
                        </div>
                      </div>
                    )}

                    <div className="flex items-center gap-3 p-4 bg-gray-50 rounded-xl hover:bg-gray-100 transition-colors">
                      <input
                        type="checkbox"
                        checked={postAdoptionForm.is_diseased}
                        onChange={(e) =>
                          setPostAdoptionForm({
                            ...postAdoptionForm,
                            is_diseased: e.target.checked,
                          })
                        }
                        className="w-5 h-5 rounded border-2 border-gray-300 text-primary-blue focus:ring-2 focus:ring-primary-blue focus:ring-offset-2 cursor-pointer"
                      />
                      <label className="text-sm font-medium text-gray-700 cursor-pointer select-none">
                        Has Health Conditions
                      </label>
                    </div>

                    {postAdoptionForm.is_diseased && (
                      <div className="ml-8 flex flex-col animate-fadeIn">
                        <label className="text-sm font-semibold text-gray-700 mb-2">
                          Health Condition Description
                        </label>
                        <textarea
                          rows="3"
                          value={postAdoptionForm.disease_description}
                          onChange={(e) =>
                            setPostAdoptionForm({
                              ...postAdoptionForm,
                              disease_description: e.target.value,
                            })
                          }
                          className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-primary-blue focus:outline-none transition-colors resize-none"
                          placeholder="Describe any health conditions or special care needs..."
                        />
                      </div>
                    )}
                  </div>

                  <button
                    type="submit"
                    disabled={submitLoading}
                    className="w-full px-6 py-4 bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow text-white font-bold rounded-xl hover:shadow-lg hover:scale-105 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 disabled:hover:shadow-none"
                  >
                    {submitLoading ? (
                      <span className="flex items-center justify-center gap-2">
                        <svg
                          className="animate-spin h-5 w-5"
                          viewBox="0 0 24 24"
                        >
                          <circle
                            className="opacity-25"
                            cx="12"
                            cy="12"
                            r="10"
                            stroke="currentColor"
                            strokeWidth="4"
                            fill="none"
                          />
                          <path
                            className="opacity-75"
                            fill="currentColor"
                            d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                          />
                        </svg>
                        Posting...
                      </span>
                    ) : (
                      "Post Pet for Adoption"
                    )}
                  </button>
                </form>
              </div>
            )}

            {activeTab === "my-adoption-posts" && (
              <div className="my-adoption-posts-section">
                <div className="section-header">
                  <span className="material-icons">article</span>
                  MY ADOPTION POSTS ({myAdoptionPosts.length})
                </div>
                <div className="reports-grid">
                  {loading ? (
                    <div className="loading">
                      Loading your adoption posts...
                    </div>
                  ) : myAdoptionPosts.length > 0 ? (
                    myAdoptionPosts.map((post) => (
                      <div
                        key={post.id}
                        className="dashboard-pet-card my-adoption-post"
                      >
                        <div className="pet-card-image">
                          <img
                            src={getImageUrl(post.image)}
                            alt={post.name}
                            onError={(e) => {
                              e.target.src = "/default-pet.png";
                            }}
                          />
                          <div className="pet-name-overlay">
                            <h3>{post.name}</h3>
                          </div>
                        </div>
                        <div className="pet-card-info">
                          <div className="pet-type">{post.type}</div>
                          <div className="pet-details">
                            {post.breed && (
                              <span className="pet-breed">{post.breed}</span>
                            )}
                            <span className="pet-age">
                              🎂 {post.age} years old
                            </span>
                            <span className="pet-gender">
                              {post.gender === "Male" ? "♂️" : "♀️"}{" "}
                              {post.gender}
                            </span>
                            {post.location && (
                              <span className="pet-location">
                                📍 {post.location}
                              </span>
                            )}
                          </div>
                          <div className="pet-description">
                            {post.description
                              ? post.description.length > 100
                                ? `${post.description.substring(0, 100)}...`
                                : post.description
                              : "No description available"}
                          </div>
                          <div className="pet-medical-info">
                            {post.is_vaccinated && (
                              <span className="badge vaccinated">
                                ✓ Vaccinated
                              </span>
                            )}
                            {post.is_diseased && (
                              <span className="badge health-issue">
                                ⚠ Health Condition
                              </span>
                            )}
                          </div>
                          <div
                            className={`pet-status-badge status-${post.report_status}`}
                          >
                            {post.report_status === "pending" &&
                              "⏳ PENDING ADMIN REVIEW"}
                            {post.report_status === "accepted" &&
                              "✅ APPROVED - LIVE"}
                            {post.report_status === "rejected" && "❌ REJECTED"}
                          </div>
                          {post.admin_comment && (
                            <div className="admin-comment">
                              <strong>Admin Comment:</strong>{" "}
                              {post.admin_comment}
                            </div>
                          )}
                          <div className="post-date">
                            Posted:{" "}
                            {new Date(post.created_at).toLocaleDateString()}
                          </div>
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="no-reports">
                      <span className="material-icons">article</span>
                      <p>You haven't posted any pets for adoption yet</p>
                    </div>
                  )}
                </div>
              </div>
            )}

            {activeTab === "profile" && (
              <div className="bg-gradient-to-br from-slate-50 to-blue-50 rounded-2xl shadow-xl p-8 border border-blue-100">
                <div className="flex items-center gap-3 mb-6">
                  <span className="material-icons text-3xl text-primary-blue">person</span>
                  <h2 className="text-2xl font-bold bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                    PROFILE MANAGEMENT
                  </h2>
                </div>

                <div className="grid md:grid-cols-3 gap-8">
                  {/* Profile Image Section */}
                  <div className="md:col-span-1 flex flex-col items-center">
                    <div className="relative w-48 h-48 mb-6">
                      {profileImagePreview ? (
                        <img
                          src={profileImagePreview}
                          alt="Profile"
                          className="w-full h-full rounded-full object-cover border-4 border-primary-blue shadow-xl"
                        />
                      ) : (
                        <div className="w-full h-full rounded-full bg-gradient-to-br from-blue-100 to-teal-100 flex items-center justify-center border-4 border-primary-blue shadow-xl">
                          <span className="material-icons text-6xl text-primary-blue">person</span>
                        </div>
                      )}
                    </div>

                    {isEditingProfile && (
                      <div className="w-full">
                        <label
                          htmlFor="profile-image-input"
                          className="flex items-center justify-center gap-2 px-4 py-3 bg-gradient-to-r from-primary-blue to-primary-teal text-white rounded-xl cursor-pointer hover:shadow-lg transform hover:scale-105 transition-all duration-200"
                        >
                          <span className="material-icons">photo_camera</span>
                          <span className="font-semibold">Change Photo</span>
                        </label>
                        <input
                          id="profile-image-input"
                          type="file"
                          accept="image/*"
                          onChange={handleProfileImageChange}
                          className="hidden"
                        />
                      </div>
                    )}
                  </div>

                  {/* Profile Details Section */}
                  <div className="md:col-span-2">
                    <div className="bg-white rounded-2xl p-6 shadow-lg border border-blue-100 mb-6">
                      <div className="flex items-start justify-between mb-6">
                        <div>
                          <h3 className="text-2xl font-bold text-gray-800">
                            {profileData.first_name}{" "}
                            {profileData.last_name || user?.username}
                          </h3>
                          <p className="text-gray-500 mt-1">{profileData.email}</p>
                        </div>

                        {!isEditingProfile ? (
                          <button
                            className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-primary-blue to-primary-teal text-white rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-200"
                            onClick={() => setIsEditingProfile(true)}
                          >
                            <span className="material-icons text-sm">edit</span>
                            <span className="font-semibold">Edit Profile</span>
                          </button>
                        ) : (
                          <div className="flex gap-2">
                            <button
                              className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-green-500 to-green-600 text-white rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
                              onClick={handleProfileSubmit}
                              disabled={submitLoading}
                            >
                              <span className="material-icons text-sm">save</span>
                              <span className="font-semibold">{submitLoading ? "Saving..." : "Save"}</span>
                            </button>
                            <button
                              className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-red-500 to-red-600 text-white rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-200"
                              onClick={() => {
                                setIsEditingProfile(false);
                                setProfileImage(null);
                                setProfileImagePreview(
                                  profileData.profile_picture
                                );
                              }}
                            >
                              <span className="material-icons text-sm">cancel</span>
                              <span className="font-semibold">Cancel</span>
                            </button>
                          </div>
                        )}
                      </div>

                      {isEditingProfile ? (
                        <form
                          onSubmit={handleProfileSubmit}
                          className="space-y-4"
                        >
                          <div className="grid md:grid-cols-2 gap-4">
                            <div>
                              <label className="block text-sm font-semibold text-gray-700 mb-2">
                                First Name
                              </label>
                              <input
                                type="text"
                                name="first_name"
                                value={profileData.first_name}
                                onChange={handleProfileInputChange}
                                placeholder="Enter first name"
                                className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 outline-none transition-all duration-200"
                              />
                            </div>
                            <div>
                              <label className="block text-sm font-semibold text-gray-700 mb-2">
                                Last Name
                              </label>
                              <input
                                type="text"
                                name="last_name"
                                value={profileData.last_name}
                                onChange={handleProfileInputChange}
                                placeholder="Enter last name"
                                className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 outline-none transition-all duration-200"
                              />
                            </div>
                          </div>

                          <div className="grid md:grid-cols-2 gap-4">
                            <div>
                              <label className="block text-sm font-semibold text-gray-700 mb-2">
                                Email
                              </label>
                              <input
                                type="email"
                                name="email"
                                value={profileData.email}
                                onChange={handleProfileInputChange}
                                placeholder="Enter email address"
                                className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 outline-none transition-all duration-200"
                              />
                            </div>
                            <div>
                              <label className="block text-sm font-semibold text-gray-700 mb-2">
                                Phone Number
                              </label>
                              <input
                                type="tel"
                                name="phone_no"
                                value={profileData.phone_no}
                                onChange={handleProfileInputChange}
                                placeholder="Enter phone number"
                                className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 outline-none transition-all duration-200"
                              />
                            </div>
                          </div>

                          <div className="grid md:grid-cols-2 gap-4">
                            <div>
                              <label className="block text-sm font-semibold text-gray-700 mb-2">
                                City
                              </label>
                              <input
                                type="text"
                                name="city"
                                value={profileData.city}
                                onChange={handleProfileInputChange}
                                placeholder="Enter city"
                                className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 outline-none transition-all duration-200"
                              />
                            </div>
                            <div>
                              <label className="block text-sm font-semibold text-gray-700 mb-2">
                                State
                              </label>
                              <input
                                type="text"
                                name="state"
                                value={profileData.state}
                                onChange={handleProfileInputChange}
                                placeholder="Enter state"
                                className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 outline-none transition-all duration-200"
                              />
                            </div>
                          </div>

                          <div className="grid md:grid-cols-2 gap-4">
                            <div>
                              <label className="block text-sm font-semibold text-gray-700 mb-2">
                                PIN Code
                              </label>
                              <input
                                type="text"
                                name="pincode"
                                value={profileData.pincode}
                                onChange={handleProfileInputChange}
                                placeholder="Enter PIN code"
                                className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 outline-none transition-all duration-200"
                              />
                            </div>
                            <div>
                              <label className="block text-sm font-semibold text-gray-700 mb-2">
                                Gender
                              </label>
                              <select
                                name="gender"
                                value={profileData.gender}
                                onChange={handleProfileInputChange}
                                className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 outline-none transition-all duration-200 bg-white"
                              >
                                <option value="">Select Gender</option>
                                <option value="Male">Male</option>
                                <option value="Female">Female</option>
                                <option value="Other">Other</option>
                              </select>
                            </div>
                          </div>

                          <div>
                            <label className="block text-sm font-semibold text-gray-700 mb-2">
                              Address
                            </label>
                            <textarea
                              name="address"
                              value={profileData.address}
                              onChange={handleProfileInputChange}
                              placeholder="Enter complete address"
                              rows="3"
                              className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 outline-none transition-all duration-200 resize-none"
                            />
                          </div>
                        </form>
                      ) : (
                        <div className="grid md:grid-cols-2 gap-4">
                          <div className="p-4 bg-gradient-to-br from-blue-50 to-blue-100 rounded-xl">
                            <span className="text-xs font-bold text-gray-600 uppercase tracking-wide">Phone</span>
                            <p className="text-lg font-semibold text-gray-800 mt-1">
                              {profileData.phone_no || "Not provided"}
                            </p>
                          </div>
                          <div className="p-4 bg-gradient-to-br from-teal-50 to-teal-100 rounded-xl">
                            <span className="text-xs font-bold text-gray-600 uppercase tracking-wide">City</span>
                            <p className="text-lg font-semibold text-gray-800 mt-1">
                              {profileData.city || "Not provided"}
                            </p>
                          </div>
                          <div className="p-4 bg-gradient-to-br from-purple-50 to-purple-100 rounded-xl">
                            <span className="text-xs font-bold text-gray-600 uppercase tracking-wide">State</span>
                            <p className="text-lg font-semibold text-gray-800 mt-1">
                              {profileData.state || "Not provided"}
                            </p>
                          </div>
                          <div className="p-4 bg-gradient-to-br from-pink-50 to-pink-100 rounded-xl">
                            <span className="text-xs font-bold text-gray-600 uppercase tracking-wide">PIN Code</span>
                            <p className="text-lg font-semibold text-gray-800 mt-1">
                              {profileData.pincode || "Not provided"}
                            </p>
                          </div>
                          <div className="p-4 bg-gradient-to-br from-yellow-50 to-yellow-100 rounded-xl">
                            <span className="text-xs font-bold text-gray-600 uppercase tracking-wide">Gender</span>
                            <p className="text-lg font-semibold text-gray-800 mt-1">
                              {profileData.gender || "Not provided"}
                            </p>
                          </div>
                          <div className="p-4 bg-gradient-to-br from-indigo-50 to-indigo-100 rounded-xl md:col-span-2">
                            <span className="text-xs font-bold text-gray-600 uppercase tracking-wide">Address</span>
                            <p className="text-lg font-semibold text-gray-800 mt-1">
                              {profileData.address || "Not provided"}
                            </p>
                          </div>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            )}
          </main>
        </div>
      </div>

      {/* Pet Detail Modal */}
      {showDetailModal && (
        <div
          className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4 animate-fadeIn"
          onClick={closeDetailModal}
        >
          <div
            className="bg-white rounded-3xl shadow-2xl max-w-4xl w-full max-h-[90vh] overflow-y-auto relative animate-slideUp"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Close Button */}
            <button
              onClick={closeDetailModal}
              className="absolute top-4 right-4 z-10 bg-white/90 hover:bg-red-500 text-gray-600 hover:text-white rounded-full p-2 shadow-lg transition-all duration-300 transform hover:scale-110"
            >
              <span className="material-icons">close</span>
            </button>

            {detailLoading ? (
              <div className="flex items-center justify-center py-20">
                <div className="text-center">
                  <div className="inline-block animate-spin rounded-full h-12 w-12 border-b-2 border-primary-blue mb-4"></div>
                  <p className="text-gray-600">Loading pet details...</p>
                </div>
              </div>
            ) : selectedPetDetails ? (
              <div className="p-8">
                {/* Header Section with Image */}
                <div className="flex flex-col md:flex-row gap-6 mb-6">
                  {/* Pet Image */}
                  <div className="md:w-1/2">
                    <div className="relative rounded-2xl overflow-hidden shadow-xl">
                      <img
                        src={getImageUrl(selectedPetDetails.pet_info.image)}
                        alt={selectedPetDetails.pet_info.name}
                        className="w-full h-96 object-cover"
                        onError={(e) => {
                          e.target.src = "/default-pet.png";
                        }}
                      />
                      <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/70 to-transparent p-4">
                        <h2 className="text-3xl font-bold text-white">
                          {selectedPetDetails.pet_info.name}
                        </h2>
                      </div>
                    </div>
                  </div>

                  {/* Quick Info */}
                  <div className="md:w-1/2 space-y-4">
                    <div className="inline-block px-4 py-2 bg-gradient-to-r from-primary-blue to-primary-teal text-white rounded-full text-sm font-semibold shadow-lg">
                      {selectedPetDetails.pet_info.type}
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                      <div className="bg-gradient-to-br from-blue-50 to-blue-100 p-4 rounded-xl">
                        <span className="text-xs text-gray-600 font-semibold">
                          BREED
                        </span>
                        <p className="text-lg font-bold text-gray-800">
                          {selectedPetDetails.pet_info.breed || "Unknown"}
                        </p>
                      </div>
                      <div className="bg-gradient-to-br from-teal-50 to-teal-100 p-4 rounded-xl">
                        <span className="text-xs text-gray-600 font-semibold">
                          AGE
                        </span>
                        <p className="text-lg font-bold text-gray-800">
                          {selectedPetDetails.pet_info.age || "Unknown"} years
                        </p>
                      </div>
                      <div className="bg-gradient-to-br from-purple-50 to-purple-100 p-4 rounded-xl">
                        <span className="text-xs text-gray-600 font-semibold">
                          GENDER
                        </span>
                        <p className="text-lg font-bold text-gray-800">
                          {selectedPetDetails.pet_info.gender || "Unknown"}
                        </p>
                      </div>
                      <div className="bg-gradient-to-br from-pink-50 to-pink-100 p-4 rounded-xl">
                        <span className="text-xs text-gray-600 font-semibold">
                          COLOR
                        </span>
                        <p className="text-lg font-bold text-gray-800">
                          {selectedPetDetails.pet_info.colour || "Unknown"}
                        </p>
                      </div>
                    </div>

                    <div
                      className={`px-4 py-3 rounded-xl text-center font-semibold ${
                        selectedPetDetails.pet_info.status === "available"
                          ? "bg-green-100 text-green-700"
                          : selectedPetDetails.pet_info.status === "adopted"
                          ? "bg-blue-100 text-blue-700"
                          : "bg-gray-100 text-gray-700"
                      }`}
                    >
                      {selectedPetDetails.pet_info.status?.toUpperCase()}
                    </div>
                  </div>
                </div>

                {/* Description */}
                <div className="mb-6 bg-gradient-to-br from-slate-50 to-blue-50 p-6 rounded-2xl border border-blue-100">
                  <h3 className="text-xl font-bold text-gray-800 mb-3 flex items-center gap-2">
                    <span className="material-icons text-primary-blue">
                      description
                    </span>
                    Description
                  </h3>
                  <p className="text-gray-700 leading-relaxed">
                    {selectedPetDetails.pet_info.description ||
                      "No description available"}
                  </p>
                </div>

                {/* Location Info */}
                <div className="mb-6 bg-gradient-to-br from-slate-50 to-blue-50 p-6 rounded-2xl border border-blue-100">
                  <h3 className="text-xl font-bold text-gray-800 mb-3 flex items-center gap-2">
                    <span className="material-icons text-primary-teal">
                      location_on
                    </span>
                    Location Details
                  </h3>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div>
                      <span className="text-sm text-gray-600 font-semibold">
                        Location
                      </span>
                      <p className="text-gray-800">
                        {selectedPetDetails.pet_info.location ||
                          "Not specified"}
                      </p>
                    </div>
                    <div>
                      <span className="text-sm text-gray-600 font-semibold">
                        City
                      </span>
                      <p className="text-gray-800">
                        {selectedPetDetails.pet_info.city || "Not specified"}
                      </p>
                    </div>
                    <div>
                      <span className="text-sm text-gray-600 font-semibold">
                        State
                      </span>
                      <p className="text-gray-800">
                        {selectedPetDetails.pet_info.state || "Not specified"}
                      </p>
                    </div>
                  </div>
                </div>

                {/* Medical History */}
                {selectedPetDetails.medical_history && (
                  <div className="mb-6 bg-gradient-to-br from-green-50 to-green-100 p-6 rounded-2xl border border-green-200">
                    <h3 className="text-xl font-bold text-gray-800 mb-3 flex items-center gap-2">
                      <span className="material-icons text-green-600">
                        medical_services
                      </span>
                      Medical History
                    </h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div className="bg-white p-4 rounded-xl">
                        <span className="text-sm text-gray-600 font-semibold">
                          Vaccination Status
                        </span>
                        <p className="text-gray-800 flex items-center gap-2 mt-1">
                          {selectedPetDetails.pet_info.is_vaccinated ? (
                            <>
                              <span className="material-icons text-green-600">
                                check_circle
                              </span>
                              Vaccinated
                            </>
                          ) : (
                            <>
                              <span className="material-icons text-red-600">
                                cancel
                              </span>
                              Not Vaccinated
                            </>
                          )}
                        </p>
                      </div>
                      <div className="bg-white p-4 rounded-xl">
                        <span className="text-sm text-gray-600 font-semibold">
                          Health Status
                        </span>
                        <p className="text-gray-800 flex items-center gap-2 mt-1">
                          {selectedPetDetails.pet_info.is_diseased ? (
                            <>
                              <span className="material-icons text-orange-600">
                                warning
                              </span>
                              Has Health Condition
                            </>
                          ) : (
                            <>
                              <span className="material-icons text-green-600">
                                check_circle
                              </span>
                              Healthy
                            </>
                          )}
                        </p>
                      </div>
                      {selectedPetDetails.medical_history.vaccine_name && (
                        <div className="bg-white p-4 rounded-xl">
                          <span className="text-sm text-gray-600 font-semibold">
                            Vaccine Name
                          </span>
                          <p className="text-gray-800 mt-1">
                            {selectedPetDetails.medical_history.vaccine_name}
                          </p>
                        </div>
                      )}
                      {selectedPetDetails.medical_history
                        .last_vaccinated_date && (
                        <div className="bg-white p-4 rounded-xl">
                          <span className="text-sm text-gray-600 font-semibold">
                            Last Vaccinated
                          </span>
                          <p className="text-gray-800 mt-1">
                            {new Date(
                              selectedPetDetails.medical_history.last_vaccinated_date
                            ).toLocaleDateString()}
                          </p>
                        </div>
                      )}
                      {selectedPetDetails.medical_history.disease_name && (
                        <div className="bg-white p-4 rounded-xl col-span-2">
                          <span className="text-sm text-gray-600 font-semibold">
                            Disease/Condition
                          </span>
                          <p className="text-gray-800 mt-1">
                            {selectedPetDetails.medical_history.disease_name}
                          </p>
                          {selectedPetDetails.medical_history.stage && (
                            <p className="text-sm text-gray-600 mt-1">
                              Stage: {selectedPetDetails.medical_history.stage}
                            </p>
                          )}
                        </div>
                      )}
                      {selectedPetDetails.medical_history.treatment_name && (
                        <div className="bg-white p-4 rounded-xl col-span-2">
                          <span className="text-sm text-gray-600 font-semibold">
                            Treatment
                          </span>
                          <p className="text-gray-800 mt-1">
                            {selectedPetDetails.medical_history.treatment_name}
                          </p>
                        </div>
                      )}
                    </div>
                  </div>
                )}

                {/* Physical Details */}
                <div className="mb-6 bg-gradient-to-br from-slate-50 to-blue-50 p-6 rounded-2xl border border-blue-100">
                  <h3 className="text-xl font-bold text-gray-800 mb-3 flex items-center gap-2">
                    <span className="material-icons text-primary-blue">
                      info
                    </span>
                    Physical Details
                  </h3>
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    <div>
                      <span className="text-sm text-gray-600 font-semibold">
                        Weight
                      </span>
                      <p className="text-gray-800">
                        {selectedPetDetails.pet_info.weight
                          ? `${selectedPetDetails.pet_info.weight} kg`
                          : "Not specified"}
                      </p>
                    </div>
                    <div>
                      <span className="text-sm text-gray-600 font-semibold">
                        Color
                      </span>
                      <p className="text-gray-800">
                        {selectedPetDetails.pet_info.colour || "Not specified"}
                      </p>
                    </div>
                    <div className="col-span-2">
                      <span className="text-sm text-gray-600 font-semibold">
                        Created
                      </span>
                      <p className="text-gray-800">
                        {new Date(
                          selectedPetDetails.pet_info.created_at
                        ).toLocaleDateString()}
                      </p>
                    </div>
                  </div>
                </div>

                {/* Reports Section */}
                {selectedPetDetails.reports &&
                  selectedPetDetails.reports.length > 0 && (
                    <div className="mb-6 bg-gradient-to-br from-yellow-50 to-yellow-100 p-6 rounded-2xl border border-yellow-200">
                      <h3 className="text-xl font-bold text-gray-800 mb-3 flex items-center gap-2">
                        <span className="material-icons text-yellow-600">
                          report
                        </span>
                        Reports ({selectedPetDetails.total_reports})
                      </h3>
                      <div className="space-y-3">
                        {selectedPetDetails.reports
                          .slice(0, 3)
                          .map((report) => (
                            <div
                              key={report.id}
                              className="bg-white p-4 rounded-xl"
                            >
                              <div className="flex items-center justify-between mb-2">
                                <span className="font-semibold text-gray-800">
                                  {report.user_name}
                                </span>
                                <span
                                  className={`px-3 py-1 rounded-full text-xs font-semibold ${
                                    report.report_status === "accepted"
                                      ? "bg-green-100 text-green-700"
                                      : report.report_status === "pending"
                                      ? "bg-yellow-100 text-yellow-700"
                                      : "bg-red-100 text-red-700"
                                  }`}
                                >
                                  {report.report_status}
                                </span>
                              </div>
                              <p className="text-sm text-gray-600">
                                {report.description}
                              </p>
                              <span className="text-xs text-gray-500 mt-2 block">
                                {new Date(
                                  report.created_at
                                ).toLocaleDateString()}
                              </span>
                            </div>
                          ))}
                      </div>
                    </div>
                  )}

                {/* Action Buttons */}
                <div className="flex gap-4 mt-6">
                  <button
                    onClick={closeDetailModal}
                    className="flex-1 px-6 py-3 bg-gradient-to-r from-gray-500 to-gray-600 text-white font-semibold rounded-xl hover:shadow-xl transform hover:scale-105 transition-all duration-300"
                  >
                    Close
                  </button>
                  {selectedPetDetails.pet_info.status === "available" && (
                    <button
                      className="flex-1 px-6 py-3 bg-gradient-to-r from-primary-blue to-primary-teal text-white font-semibold rounded-xl hover:shadow-xl transform hover:scale-105 transition-all duration-300 flex items-center justify-center gap-2"
                      onClick={() => {
                        closeDetailModal();
                        setActiveTab("adopt-pet");
                      }}
                    >
                      <span className="material-icons">favorite</span>
                      Adopt This Pet
                    </button>
                  )}
                </div>
              </div>
            ) : (
              <div className="flex items-center justify-center py-20">
                <p className="text-gray-600">No details available</p>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default UserDashboard;
